import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"业务说明（用例）","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/service_analysis.md","filePath":"knowledge/service_analysis.md","lastUpdated":null}'),r={name:"knowledge/service_analysis.md"};function o(s,l,n,d,_,c){return e(),i("div",null,[...l[0]||(l[0]=[t('<h1 id="业务说明-用例" tabindex="-1">业务说明（用例） <a class="header-anchor" href="#业务说明-用例" aria-label="Permalink to &quot;业务说明（用例）&quot;">​</a></h1><h2 id="登录用例1" tabindex="-1">登录用例<a href="https://t.qidianla.com/1159980.html" target="_blank" rel="noreferrer">1</a> <a class="header-anchor" href="#登录用例1" aria-label="Permalink to &quot;登录用例[1]&quot;">​</a></h2><p>正常流程：输入手机号、输入密码，判断正误，登录框关闭，回到登录前页面，获取登录状态及用户信息显示。</p><p>异常流程：</p><ol><li>未输入手机号，登录按钮无效</li><li>未输入密码，登录按钮无效</li><li>手机号非11位，登录按钮无效</li><li>手机号获取焦点弹出输入框无法输入字母</li><li>手机号输入框超过11位数字后无法继续输入</li><li>输入手机号错误，点击登录，提示账号未注册</li><li>输入手机号正确，密码错误，点击登录，提示密码错误</li><li>输入手机号密码正确，网络异常，点击登录，提示网络异常，稍后再试</li><li>点击忘记密码，输入手机号未存在数据库，点击发送验证码，提示手机号未注册</li></ol><h2 id="评论用例" tabindex="-1">评论用例 <a class="header-anchor" href="#评论用例" aria-label="Permalink to &quot;评论用例&quot;">​</a></h2><p>正常流程：点击评论框获取焦点，弹出输入框，输入评论内容，点击发布，关闭输入框，刷新页面，更新评论。</p><p>异常流程：</p><ol><li>未输入内容，发布按钮失效</li><li>内容不足15字，发布按钮失效</li><li>内容超过140字不能继续输入</li><li>失去网络连接点击发布，提示网络异常，请稍后再试</li><li>网络延迟多次发布，提示同一用户不能重复发布相同内容评论</li><li>输入内容包含敏感词，使用*替代</li></ol>',9)])])}const m=a(r,[["render",o]]);export{h as __pageData,m as default};
